int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int i;
    const uint8_t *cursor;
    const struct ieee80211_radiotap_namespace *ns;

    memset(iterator, 0, sizeof(*iterator));
    iterator->this_arg = (uint8_t *)radiotap_header + sizeof(*radiotap_header);
    iterator->arg = iterator->this_arg;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->radiotap = radiotap_header;
    iterator->is_radiotap = 1;

    if (max_length < (int)(sizeof(*radiotap_header)))
        return -EINVAL;

    if (le16toh(radiotap_header->it_version) != 0)
        return -EINVAL;

    cursor = radiotap_header->it_present;
    for (i = 0; i < 4; i++) {
        uint32_t field;
        if (i < sizeof(radiotap_header->it_present))
            field = le32toh(*((uint32_t *)cursor + i));
        else
            field = 0;
        iterator->present[i] = field;
    }

    ns = ieee80211_radiotap_vendor_namespaces;
    while (ns && ns->vendor_id != 0) {
        if (ns->vendor_id == le32toh(radiotap_header->it_vendor_id))
            break;
        ns++;
    }

    if (!ns)
        return -EINVAL;

    iterator->ns = ns;

    return 0;
}

int ieee80211_radiotap_iterator_init(
    struct ieee80211_radiotap_iterator *iterator,
    struct ieee80211_radiotap_header *radiotap_header,
    int max_length,
    const struct ieee80211_radiotap_vendor_namespaces *vns) {
    if (!iterator || !radiotap_header || max_length < 0 || !vns) {
        return -EINVAL;
    }

    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->this_arg = NULL;
    iterator->parse_arg = NULL;
    iterator->is_radiotap = 0;
    iterator->current = 0;
    iterator->n_bits = 0;
    iterator->is_first = 1;

    if (max_length < sizeof(*radiotap_header)) {
        return -EINVAL;
    }

    if ((radiotap_header->it_version & IEEE80211_RADIOTAP_VERSION_MASK) != 0) {
        return -EINVAL;
    }

    if (radiotap_header->it_pad[0] != 0 || radiotap_header->it_pad[1] != 0) {
        return -EINVAL;
    }

    if (radiotap_header->it_pad[2] != 0 || radiotap_header->it_pad[3] != 0) {
        return -EINVAL;
    }

    iterator->n_bits = le16_to_cpu(radiotap_header->it_present);

    if (iterator->n_bits & IEEE80211_RADIOTAP_EXT) {
        iterator->n_bits = le16_to_cpu(*(uint16_t *)(((uint8_t *)radiotap_header) + 8));
        iterator->current = 8;
    } else {
        iterator->current = 4;
    }

    iterator->n_bits &= ~IEEE80211_RADIOTAP_EXT;
    iterator->current += 2;

    return 0;
}

int ieee80211_radiotap_iterator_init(
    struct ieee80211_radiotap_iterator *iterator,
    struct ieee80211_radiotap_header *radiotap_header,
    int max_length,
    const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int i;

    iterator->current_entry = (uint8_t *)(radiotap_header + 1);
    iterator->max_length = max_length;
    iterator->vns = vns;

    if (radiotap_header->it_version != 0) {
        return -EINVAL;
    }

    iterator->next_bitmap = le16toh(radiotap_header->it_present);
    iterator->thishdr = sizeof(struct ieee80211_radiotap_header);
    iterator->is_radiotap = 1;
    iterator->parse = IEEE80211_RADIOTAP_ITER_DONE;

    for (i = 0; i < 8; i++) {
        iterator->ext[i] = 0;
    }

    if (radiotap_header->it_present & htole16(IEEE80211_RADIOTAP_EXT)) {
        iterator->parse = IEEE80211_RADIOTAP_ITER_EXT;
        iterator->ext[0] = 1;
    }

    return 0;
}

int ieee80211_radiotap_iterator_init(
    struct ieee80211_radiotap_iterator *iterator,
    struct ieee80211_radiotap_header *radiotap_header,
    int max_length,
    const struct ieee80211_radiotap_vendor_namespaces *vns)
{
    uint32_t radiotap_len;

    if (!iterator || !radiotap_header)
        return -EINVAL;

    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->is_radiotap = 1;
    iterator->parse |= IEEE80211_RADIOTAP_PARSE_SKIP;
    iterator->parse |= IEEE80211_RADIOTAP_PARSE_ERROR;

    if (max_length < sizeof(*radiotap_header))
        return -EINVAL;

    if (radiotap_header->it_version != 0)
        return -EINVAL;

    radiotap_len = (uint32_t) le16toh(radiotap_header->it_len);
    if (radiotap_len < sizeof(*radiotap_header))
        return -EINVAL;

    if (radiotap_len > max_length)
        return -EINVAL;

    iterator->parse |= le16toh(radiotap_header->it_present);

    iterator->current = (const uint8_t *)radiotap_header;
    iterator->hdr = radiotap_header;
    iterator->align16 = 0;

    return 0;
}

int ieee80211_radiotat_iter_init(struct ieee80211_radiotap_iterator *iterator,
                                 struct ieee80211_radiotap_header *radiotap_header,
                                 int max_length,
                                 const struct ieee80211_radiotap_vendor_namespaces *vns) {
    uint32_t bitmap;

    if (!iterator || !radiotap_header || max_length < 0 || vns->count > IEEE80211_RADIOTAP_VENDOR_NS_MAX) {
        return -EINVAL;
    }

    iterator->this_arg = NULL;
    iterator->is_radiotap = 1;
    iterator->radiotap = radiotap_header;
    iterator->vns = vns;
    iterator->current = NULL;
    iterator->parse_args = 0;

    if (max_length < sizeof(struct ieee80211_radiotap_header)) {
        return -EINVAL;
    }

    if (radiotap_header->it_version != 0) {
        return -EINVAL;
    }

    bitmap = le16toh(radiotap_header->it_present);
    if (radiotap_header->it_ext) {
        if (max_length < 2 * sizeof(struct ieee80211_radiotap_header)) {
            return -EINVAL;
        }
        bitmap |= (uint32_t) le16toh(radiotap_header->it_ext);
    }

    iterator->next_index = 0;
    iterator->parse_bitmap = bitmap;
    iterator->max_length = max_length;

    return 0;
}
